def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
    - Multiplos de 3 son 'Fizz'
    - Multiplos de 5 son 'Buzz'
    - Multiplos de 15 son 'FizzBuzz'
    - Los demás son convertidos a string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales.
    Devuelve la tupla (elemento, longitud). Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_element = lista[0]
    current_racha = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            current_racha += 1
        else:
            if current_racha > max_racha:
                max_racha = current_racha
                max_element = lista[i - 1]
            current_racha = 1

    # Verificar la racha final
    if current_racha > max_racha:
        max_racha = current_racha
        max_element = lista[-1]

    return (max_element, max_racha)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []
    return [i for i in range(2, n + 1) if all(i % j != 0 for j in range(2, int(i**0.5) + 1))]

def mcd(a, b):
    """
    Devuelve el máximo común divisor de dos enteros no negativos.
    El mcd de un número con 0 es ese número.
    """
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False en caso contrario.
    """
    if not s:
        return True

    open_paren = 0
    open_bracket = 0
    open_brace = 0

    for char in s:
        if char == '(':
            open_paren += 1
        elif char == '[':
            open_bracket += 1
        elif char == '{':
            open_brace += 1
        elif char == ')':
            if open_paren == 0:
                return False
            open_paren -= 1
        elif char == ']':
            if open_bracket == 0:
                return False
            open_bracket -= 1
        elif char == '}':
            if open_brace == 0:
                return False
            open_brace -= 1

    return open_paren == 0 and open_bracket == 0 and open_brace == 0

def balanceado(s: str) -> bool:
    """
    Verifica si los paréntesis, corchetes y llaves del string están bien balanceados y anidados.
    Los demás caracteres se ignoran.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están bien balanceados, False en caso contrario.
    """
    open_paren = []
    open_bracket = []
    open_brace = []

    for char in s:
        if char == '(':
            open_paren.append(char)
        elif char == '[':
            open_bracket.append(char)
        elif char == '{':
            open_brace.append(char)
        elif char == ')':
            if not open_paren:
                return False
            open_paren.pop()
        elif char == ']':
            if not open_bracket:
                return False
            open_bracket.pop()
        elif char == '}':
            if not open_brace:
                return False
            open_brace.pop()

    return len(open_paren) == 0 and len(open_bracket) == 0 and len(open_brace) == 0

def anidar(plano: dict) -> dict:
    """
    Convierte un diccionario de claves con puntos en un diccionario anidado.

    Ejemplo: {'a.b': 1} -> {'a': {'b': 1}}

    Args:
        plano: Diccionario con claves que pueden contener puntos ('.')

    Returns:
        Diccionario anidado con las claves separadas por puntos
    """
    result = {}
    for key, value in plano.items():
        if '.' in key:
            parts = key.split('.')
            current = result
            for part in parts[:-1]:
                if part not in current:
                    current[part] = {}
                current = current[part]
            current[parts[-1]] = value
        else:
            result[key] = value
    return result

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

