def aplanar_hasta(lista: list, profundidad: int) -> list:
    """
    Aplanar una lista anidada hasta la profundidad indicada.

    Args:
        lista: Lista que puede contener elementos de cualquier tipo.
        profundidad: Nivel máximo de anidamiento a aplana.

    Returns:
        Lista plana con todos los elementos desempaquetados.
    """
    if profundidad <= 0:
        return lista
    if not isinstance(lista, list):
        raise TypeError("La lista debe ser de tipo list")

    result = []
    for item in lista:
        if isinstance(item, list):
            result.extend(aplanar_hasta(item, profundidad - 1))
        else:
            result.append(item)
    return result

